<div class="container-fluid" style="margin-top:80px;padding:25px;"><div class="panel panel-default" style="border-radius:14px;"><div class="panel-body">
<h3><i class="bi bi-book"></i> Cek Diklat</h3><p class="text-muted">Masukkan NIP untuk melihat riwayat diklat.</p>
<form method="post" action="<?= base_url('asn/cek-diklat'); ?>" class="form-inline"><div class="form-group"><input type="text" name="nip" class="form-control" value="<?= esc($nip ?? session()->get('ses_nip')); ?>" placeholder="NIP" required></div> <button class="btn btn-primary">Cari</button></form><hr>
